import json,pathlib,collections,heapq
out=pathlib.Path('/tmp/p190/transcript');rows=[]
for provider in ['claude','codex']:
 base=pathlib.Path('/private/tmp/p190/canonical/results')/('transcript-trace-'+provider)
 summary=json.load(open(base/'summary.json'))
 for phase in ['idle','active']:
  data=json.load(open(base/('trace-'+phase+'.json')))['traceEvents']
  main={(e['pid'],e['tid']) for e in data if e['name']=='thread_name' and e.get('args',{}).get('name')=='CrRendererMain'}
  events=[e for e in data if (e['pid'],e['tid']) in main and e['ph']=='X' and e.get('dur',0)>0]
  boundaries=[]
  for i,e in enumerate(events):
   boundaries.extend([(e['ts'],1,i),(e['ts']+e['dur'],-1,i)])
  boundaries.sort();active=set();heap=[];tot=collections.Counter();last=None
  for at,kind,i in boundaries:
   while heap and heap[0][2] not in active:heapq.heappop(heap)
   if last is not None and heap and at>last:
    name=events[heap[0][2]]['name']
    if name in ['FunctionCall','v8.callFunction','EvaluateScript','EventDispatch','FireAnimationFrame','TimerFire','RunMicrotasks']:category='Script and callback dispatch'
    elif name in ['Layout','UpdateLayoutTree','Paint','Layerize','PrePaint','IntersectionObserverController::computeIntersections']:category='Layout, style and rendering'
    elif 'GC' in name or 'Garbage' in name:category='Garbage collection'
    else:category='Other traced browser work'
    tot[category]+=(at-last)/1000
   if kind==1:
    active.add(i);e=events[i]
    # Prefer the innermost span, including duplicate categories at one timestamp.
    heapq.heappush(heap,(-e['ts'],e['ts']+e['dur'],i))
   else:active.discard(i)
   last=at
  task=summary['phases'][phase]['tabs']['session']['taskS']*1000
  row={'provider':provider,'phase':phase,'measurement':'Non-overlapping occupied trace wall intervals, deepest active span; diagnostic only, not sampled CPU or accepted timing','taskMetricMsRounded':task,'classifiedOccupiedMs':dict(tot),'unionOccupiedMs':sum(tot.values()),'taskMetricLessOccupiedMs':task-sum(tot.values())}
  rows.append(row);print(row)
(out/'trace-exclusive.json').write_text(json.dumps(rows,indent=2))

